import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.DrDMl0tG.js";const o="/assets/rayrai_segmentation_camera.sO8rXdHk.png",g=JSON.parse('{"title":"Rayrai Example: Segmentation Camera","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_segmentation_camera.md","filePath":"sections/examples/rayrai/rayrai_segmentation_camera.md"}'),n={name:"sections/examples/rayrai/rayrai_segmentation_camera.md"};function r(c,e,l,h,d,m){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="rayrai-example-segmentation-camera" tabindex="-1">Rayrai Example: Segmentation Camera <a class="header-anchor" href="#rayrai-example-segmentation-camera" aria-label="Permalink to &quot;Rayrai Example: Segmentation Camera&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Renders an RGB image and a segmentation image from the same camera and the same physics snapshot and shows them side by side. Every object carries a semantic class (<code>Ground</code>, <code>Box</code>, <code>Sphere</code>, <code>Cylinder</code>), so the segmentation view can be colored by class, where both boxes share one color, or by object instance, where each object has its own color. RGB is shown on the left and segmentation on the right, at 640 x 400 pixels per image.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+o+`" alt="rayrai_segmentation_camera example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_segmentation_camera</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>From the repository root, build the target and run it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./raisim_env.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rayrai_segmentation_camera</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_segmentation_camera</span></span></code></pre></div><p>See <a href="./../../BuildAndTest.html#build-examples">Build examples</a> to configure a new build directory.</p><p>On Windows, run <code>rayrai_segmentation_camera.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="semantic-classes-and-object-instances" tabindex="-1">Semantic classes and object instances <a class="header-anchor" href="#semantic-classes-and-object-instances" aria-label="Permalink to &quot;Semantic classes and object instances&quot;">​</a></h2><p>The app starts with <strong>Color by</strong> set to <strong>Semantic class</strong>. Both boxes have the same <code>Box</code> label, so they have the same segmentation color even though their RGB appearances differ. Segmentation colors visualize integer IDs; they do not come from an object&#39;s material or RGB color.</p><table tabindex="0"><thead><tr><th>Color by</th><th>Integer image used</th><th>Box A and Box B</th></tr></thead><tbody><tr><td><strong>Semantic class</strong> (default)</td><td>Semantic labels</td><td>Share one color because both have the <code>Box</code> label.</td></tr><tr><td><strong>Object instance</strong></td><td>World object indices</td><td>Have different colors because they are separate objects.</td></tr></tbody></table><p>Select <strong>Color by → Object instance</strong> in the app to color by object. The legend shows the class or object assigned to each color. Black marks pixels with no geometry within the camera&#39;s clipping range. Use <strong>Rotate camera</strong> for automatic rotation, or <strong>Camera angle</strong> to choose a view; both images move together.</p><h2 id="save-a-comparison" tabindex="-1">Save a comparison <a class="header-anchor" href="#save-a-comparison" aria-label="Permalink to &quot;Save a comparison&quot;">​</a></h2><p>Use <code>--screenshot</code> to save a 1280 x 400 PNG with RGB on the left and the semantic segmentation on the right, then exit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_segmentation_camera</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --screenshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> semantic.png</span></span></code></pre></div><p>The PNG contains the two images without the app controls or legend. Capture mode uses a hidden window and still requires a working OpenGL context.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Names the classes with <code>World::addSegmentationClass()</code> and labels each body with <code>Object::setSegmentationLabel()</code>.</li><li>Renders the color image with <code>renderWithExternalCamera()</code> and the segmentation image with <code>RayraiWindow::renderSegmentation()</code> from the same <code>raisin::Camera</code>, so the two images line up pixel for pixel.</li><li>Reads the integer ids back with <code>raisin::Camera::readSegmentation()</code> and colors them with <code>SegmentationCamera::colorize()</code>, which gives each id a fixed color; background pixels are black.</li></ul><p>See <a href="./../../Sensors.html#segmentation-camera">Segmentation camera</a> for the images, labels and the URDF and XML syntax.</p>`,23)])])}const b=a(n,[["render",r]]);export{g as __pageData,b as default};
